const options = (list,value) => list.map(([v,n])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`).join('');
function notify(text){const n=$('#toast');n.textContent=text;n.className='toast';clearTimeout(notify.timer);notify.timer=setTimeout(()=>{n.className='';n.textContent='';},4000);}
function go(view){state.view=view;state.nav=false;closeModal();render();}
function selectTask(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;state.task=id;state.project=t.project;go('task');}
function variant(key){state.variant=key;render();}
function navItem(label,view,i,count){return `<button class="nav-item ${state.view===view?'active':''}" data-action="view:${view}">${icon(i)}<span>${label}</span>${count!==undefined?`<span class="count">${count}</span>`:''}</button>`;}
function sidebar(){return `<aside class="sidebar" aria-label="主导航"><div class="brand">${mark()}<strong>PiDock</strong><span class="edition">LOCAL</span>${ib('收起导航','toggle-nav','close').replace('icon-button','icon-button mobile-nav')}</div><button class="search-button" data-action="search">${icon('search')}<span>搜索项目与任务</span><span class="key">⌘ K</span></button><div class="primary-nav">${navItem('项目总览','projects','grid')}${navItem('定时任务','schedules','clock',state.schedules.length)}</div><div class="side-label">项目 ${ib('新建项目','new-project','plus')}</div><div class="side-scroll">${state.projects.map(p=>`<button class="project-nav ${p.id===state.project?'selected':''}" data-action="project:${p.id}">${icon('folder')}<span>${esc(p.name)}</span>${p.id===state.project?icon('down'):icon('chevron')}</button>${p.id===state.project?`<div class="task-links">${state.tasks.filter(t=>t.project===p.id&&!t.archived).map(t=>`<button class="task-link ${state.view==='task'&&state.task===t.id?'active':''}" data-action="task:${t.id}"><span class="dot ${busy(t)?'blue':''}"></span><span>${esc(t.name)}</span>${t.scheduled?icon('clock'):''}</button>`).join('')}<button class="task-link" data-action="new-task"><span class="dot" style="background:transparent">+</span><span>新建任务</span></button></div>`:''}`).join('')}</div><div class="side-bottom">${navItem('已归档','archive','archive')}${navItem('设置','settings','settings')}<div class="local-status"><span class="dot blue"></span>本机 · 设计演示</div></div></aside>`;}
function rail(){return `<nav class="rail" aria-label="快捷导航">${mark()}${ib('项目总览','view:projects','grid')}${ib('定时任务','view:schedules','clock')}${ib('搜索','search','search')}<div class="bottom">${ib('已归档','view:archive','archive')}${ib('设置','view:settings','settings')}</div></nav>`;}
function topbar(){const name={projects:'项目总览',schedules:'定时任务',settings:'设置',archive:'已归档'}[state.view];return `<header class="topbar"><div class="row">${ib('展开导航','toggle-nav','menu').replace('icon-button','icon-button mobile-nav')}<div class="breadcrumb"><span>${state.view==='task'?esc(currentProject()?.name):'PiDock'}</span>${icon('chevron')}<span>${state.view==='task'?esc(currentTask()?.name):name}</span></div></div><div class="row"><span class="top-label">你的任务，有条不紊。</span>${ib('设计说明','design-notes','help')}</div></header>`;}
function reviewbar(){return `<footer class="reviewbar"><div class="row"><span class="review-tag">DESIGN REVIEW / 01</span><small>内存演示 · 刷新重置</small></div><div class="variant-picker"><button class="variant-arrow" data-action="variant:${state.variant==='A'?'B':'A'}" aria-label="上一方案">${icon('left')}</button><button class="${state.variant==='A'?'active':''}" data-action="variant:A">A · Apple 侧栏</button><button class="${state.variant==='B'?'active':''}" data-action="variant:B">B · 扁平分栏</button><button class="variant-arrow" data-action="variant:${state.variant==='A'?'B':'A'}" aria-label="下一方案">${icon('chevron')}</button></div><a class="scope-link" href="https://github.com/Leonz3n/PiDock/issues/135" target="_blank" rel="noreferrer">首版范围 #135 ↗</a><button data-action="design-notes" class="muted small">设计说明</button></footer>`;}
function render(){for(const t of state.tasks)for(const s of t.sessions)for(const m of s.messages)if(m.role==='agent'&&!m.model)m.model=s.model;document.body.className=`${state.variant==='B'?'flat ':''}${state.nav?'nav-open':''}`;$('#app').innerHTML=`<div class="shell">${rail()}${sidebar()}<button class="nav-backdrop" data-action="toggle-nav" aria-label="收起导航遮罩"></button><main class="main">${topbar()}${state.view==='task'?taskView():pageView()}</main></div>${reviewbar()}`;const url=new URL(location.href);url.searchParams.set('variant',state.variant);url.searchParams.set('page',state.view);history.replaceState({},'',url);if(state.view==='task'){const box=$('#draft');if(box)box.value=currentSession()?.draft||'';} }
function visibleSessions(t){const all=t.sessions.map((v,i)=>({v,i})).filter(({v,i})=>!v.archived||i===t.active);if(all.length<=4)return all;const selected=all.find(x=>x.i===t.active);return all.slice(0,4).some(x=>x.i===t.active)?all.slice(0,4):[...all.slice(0,3),selected].filter(Boolean);}
function taskView(){const t=currentTask();if(!t)return page('没有任务','先创建一个任务，开始对话。',btn('新建任务','new-task','primary','plus'),'');const s=currentSession();return `<div class="workspace"><section class="task-center"><div class="task-heading"><div class="eyebrow">TASK / ${String(state.tasks.indexOf(t)+1).padStart(3,'0')}</div><div class="row between"><h1>${esc(t.name)}</h1><div class="row heading-actions">${t.archived?pill('已归档'):''}${ib('任务信息','toggle-inspector','panel')}${ib('任务操作','task-menu','more')}</div></div><div class="row meta wrap"><button data-action="toggle-inspector">${icon('branch')}${t.sources.filter(x=>x.mode==='worktree').length?'独立 worktree':'已有目录'}</button><span>${t.sources.length} 个来源</span><span class="meta-extra">${t.scheduled?'定时任务':'普通任务'}</span>${t.scheduled?`<button data-action="task-rule">${state.schedules.find(rule=>rule.task===t.id)?state.schedules.find(rule=>rule.task===t.id).enabled?'规则已启用':'规则已暂停':'配置执行规则'}</button>`:''}<span class="row"><span class="dot ${s?.status==='running'?'blue':''}"></span>${t.creationFailed?'准备未完成':s?.status==='running'?'执行中':s?.status==='approval'?'等待确认':s?.status==='failed'?'执行失败':'就绪'}</span></div></div><div class="sessionbar"><div class="session-tabs" role="tablist" aria-label="任务会话">${visibleSessions(t).map(({v,i})=>`<button class="session-tab ${i===t.active?'active':''}" role="tab" aria-selected="${i===t.active}" data-action="session:${i}">${i===t.active?'<span class="dot blue"></span>':''}${esc(v.name)}${v.archived?' · 已归档':''}</button>`).join('')}</div><div class="row session-actions">${ib('新建会话','new-session','plus')}${ib('全部会话','sessions','message')}${ib('会话操作','session-menu','more')}</div></div><div class="conversation" id="conversation">${s?conversation(t,s):'<div class="empty-chat"><h2>为这个任务开始一次对话</h2><p>旧会话已删除，目录与任务仍然保留。</p>'+btn('新建会话','new-session','primary')+'</div>'}</div>${s?composer(t,s):''}</section>${state.inspector?inspector(t):''}</div>`;}
function conversation(t,s){let html='';if(t.creationFailed)html+=`<div class="status-banner error"><div>目录准备未完成<p>原目录与已完成来源保留，恢复准备后可开始执行。</p></div>${btn('查看并恢复','show-inspector','quiet')}</div>`;if(t.archived)html+=`<div class="status-banner warn"><div>任务已归档<p>定时规则已暂停，恢复任务后由你手动启用。</p></div>${btn('恢复任务','restore-task','quiet')}</div>`;if(s.archived)html+=`<div class="status-banner"><div>会话已归档<p>历史与草稿保留，恢复后可继续对话。</p></div>${btn('恢复会话','restore-session','quiet')}</div>`;if(s.status==='approval')html+=`<div class="status-banner warn"><div><strong>需要你确认本次操作</strong><p>运行 npm test · 仅限当前任务选定的来源目录</p></div>${btn('审阅操作','approval','quiet')}</div>`;if(s.status==='failed')html+=`<div class="status-banner error"><div><strong>模型连接失败</strong><p>上次请求未获得结果，输入与草稿已保留。</p></div>${btn('检查配置','view:settings','quiet')}</div>`;if(!s.messages.length)return html+`<div class="empty-chat">${mark()}<h2>从一个想法开始。</h2><p>围绕「${esc(t.name)}」继续探索，Agent 将使用当前任务选定的目录。</p><div class="suggestions"><button data-action="suggest:先了解项目结构，告诉我你的理解。">了解项目</button><button data-action="suggest:帮我制定一个清晰的实现计划。">制定计划</button><button data-action="suggest:检查最近的改动，找出需要关注的问题。">审查改动</button></div></div>`;html+='<div class="day-divider">今天 · 11 月 2 日</div>';html+=s.messages.map(m=>m.role==='user'?`<article class="message user"><div class="user-text">${esc(m.text)}</div><div class="message-time">你 · ${esc(m.time)}</div></article>`:`<article class="message"><div class="row agent-head">${mark()}<strong>PiDock</strong><span class="muted">${esc(m.model||s.model)}</span><time>${esc(m.time)}</time></div><div class="agent-content">${m.type==='seed'?seedResponse():`<p>${esc(m.text).replace(/\n/g,'<br>')}</p>`}${m.skill?`<p class="hint">技能来源：${esc(m.skill)}</p>`:''}<div class="message-foot"><span class="row">${icon('check')}本轮已完成</span><span>${m.type==='seed'?'4.2k tokens · ':''}示例回复</span></div></div></article>`).join('');if(s.status==='running')html+=`<div class="status-banner"><div class="row"><span class="dot blue pulse"></span>正在分析任务中的目录…</div>${btn('停止','stop','quiet','stop')}</div>`;return html;}
function seedResponse(){return `<p>我把创建流程收敛为三个步骤：<strong>命名任务、选择来源、确认目录方式</strong>。不再在创建时混入服务和环境配置。</p><ol><li><strong>已有目录</strong>：直接使用你选择的工作目录，修改会作用于原文件。</li><li><strong>独立 worktree</strong>：为 Git 仓库创建独立分支和工作副本，保留原有未提交修改。</li><li><strong>普通目录</strong>：始终使用原文件，单独标记为共享来源。</li></ol><details class="tool-summary"><summary><span class="row">${icon('code')}已检查 3 个文件，完成流程梳理</span><span class="muted">展开记录 ${icon('down')}</span></summary><div class="tool-details"><div class="mono">read · src/pages/CreateTask.tsx<br>read · src/data/taskSources.ts<br>command · npm test -- taskSources</div><p class="hint">工作目录：~/.pidock/tasks/task-creation/pidock<br>示例记录，退出码 0；没有执行真实命令。</p></div></details><p>创建前会看到逐项路径预览，worktree 准备失败时保留已完成的来源，并提供恢复入口。</p>`;}
function composer(t,s){const blocked=t.archived||s.archived||t.creationFailed||busy(t);const models=modelOptions();return `<div class="composer-area">${busy(t)&&!['running','approval'].includes(s.status)?'<div class="context-strip">同任务其他会话有未结束执行。你仍可编辑草稿。</div>':''}<div class="composer">${s.skill?`<div class="context-strip">${icon('book')} $${esc(s.skill.name)}<span class="grow"></span>${ib('移除技能引用','remove-skill','close')}</div>`:''}<textarea id="draft" aria-label="消息草稿" placeholder="描述你的想法，或输入 $ 选择技能…" rows="2" ${t.archived||s.archived?'disabled':''}></textarea><div class="composer-controls"><div class="composer-left">${ib('引用任务来源','reference','plus')}<button class="row" data-action="permission">${icon('shield')}<span class="permission-label">${s.permission==='read'?'只读模式':'操作需确认'}</span>${icon('down')}</button></div><div class="composer-right"><select id="model-select" aria-label="会话模型">${models.map(m=>`<option value="${esc(m.provider+'|'+m.model)}" ${m.provider===s.provider&&m.model===s.model?'selected':''}>${esc(m.model)}</option>`).join('')}${!models.some(m=>m.provider===s.provider&&m.model===s.model)?`<option selected disabled>原模型不可用</option>`:''}</select><button class="send" data-action="${s.status==='running'?'stop':'send'}" aria-label="${s.status==='running'?'停止生成':'发送消息'}" ${blocked&&s.status!=='running'?'disabled':''}>${icon(s.status==='running'?'stop':'arrow')}</button></div></div></div><div class="composer-note"><span>↵ 发送 · Shift ↵ 换行 · 本地原型</span><span>${s.context?`上下文 ${s.context}%`:'上下文 0%'} <button data-action="usage">ⓘ</button>　·　$ 技能</span></div></div>`;}
function inspector(t){return `<aside class="inspector" aria-label="任务信息"><div class="inspector-head"><h2>任务信息</h2>${ib('关闭任务信息','toggle-inspector','close')}</div><div class="inspector-body"><div class="section-label">文件来源 / ${String(t.sources.length).padStart(2,'0')}</div>${t.sources.map(src=>`<div class="source-card"><div class="source-title">${icon(src.kind==='git'?'branch':'folder')}<strong>${esc(src.name)}</strong><span class="grow"></span>${src.mode==='worktree'?pill(t.creationFailed?'准备失败':'独立副本',t.creationFailed?'warn':'blue'):pill('共享原文件')}</div><div class="source-path mono">${esc(src.path)}</div><div class="source-meta"><span>${src.kind==='git'?esc(src.branch||'当前分支'):'普通目录'}</span><span>${src.mode==='worktree'?'基线 '+esc(src.base):'已有目录'}</span></div></div>`).join('')}<div class="inspector-section"><div class="section-label">会话配置</div><div class="inspector-fact"><span>当前模型</span><span>${esc(currentSession()?.model||'未选择')}</span></div><div class="inspector-fact"><span>写入权限</span><span>${currentSession()?.permission==='read'?'仅允许读取':'操作前确认'}</span></div><div class="inspector-fact"><span>会话数量</span><span>${t.sessions.length} 个</span></div></div><div class="inspector-section"><div class="section-label">目录边界</div><p class="hint">独立 worktree 只隔离对应的工作副本。已有工作目录和普通目录共享原文件，写操作仍需协调。</p></div>${t.creationFailed?`<div class="status-banner error inspector-section"><div>${esc(t.sources.find(src=>src.mode==='worktree')?.name||'工作副本')} 准备失败<p>无法获取远程基线。不会回退使用缓存。</p>${btn('恢复准备','recover-worktree','quiet')}</div></div>`:''}</div><div class="inspector-footer">${icon('shield')}所有路径与状态均为演示数据</div></aside>`;}
function page(title,description,action,body){return `<section class="page"><div class="page-inner"><header class="page-header"><div><h1>${title}</h1><p>${description}</p></div>${action}</header>${body}</div></section>`;}
function pageView(){if(state.view==='projects')return projectsPage();if(state.view==='settings')return settingsPage();if(state.view==='schedules')return schedulesPage();return archivePage();}
function projectsPage(){const p=currentProject(),tasks=state.tasks.filter(t=>t.project===p.id&&!t.archived);return page(esc(p.name),'把相关的目录和任务，放在一起。',`<div class="row">${ib('编辑项目','edit-project','edit')}${btn('新建任务','new-task','primary','plus')}</div>`,`<div class="stats"><div class="stat"><small>进行中的任务</small><strong>${tasks.length.toString().padStart(2,'0')}</strong></div><div class="stat"><small>文件来源</small><strong>${p.sources.length.toString().padStart(2,'0')}</strong></div><div class="stat"><small>定时任务</small><strong>${tasks.filter(t=>t.scheduled).length.toString().padStart(2,'0')}</strong></div></div><div class="section-heading"><h2>任务</h2><span class="hint">${esc(p.description)}</span></div><div class="page-tabs"><button class="page-tab ${state.taskFilter==='all'?'active':''}" data-action="filter:all">全部任务</button><button class="page-tab ${state.taskFilter==='manual'?'active':''}" data-action="filter:manual">普通任务</button><button class="page-tab ${state.taskFilter==='scheduled'?'active':''}" data-action="filter:scheduled">定时任务</button></div><div class="list">${tasks.filter(t=>state.taskFilter==='all'||(state.taskFilter==='scheduled'===t.scheduled)).map(t=>`<button class="list-row" data-action="task:${t.id}"><span class="list-icon">${icon(t.scheduled?'clock':'message')}</span><span class="grow"><h3>${esc(t.name)}</h3><p>${t.sources.length} 个来源 · ${t.sessions.length} 个会话 · ${t.sources.some(s=>s.mode==='worktree')?'独立 worktree':'已有目录'}</p></span><span class="tail">${pill(busy(t)?'执行中':'就绪',busy(t)?'blue':'')}<span class="updated">今天</span>${icon('chevron')}</span></button>`).join('')||'<div class="list-row muted">还没有这类任务。</div>'}</div><section class="source-list"><div class="section-heading"><h2>项目来源</h2><button data-action="add-source">添加来源 ＋</button></div><div class="list">${p.sources.map(src=>`<div class="list-row"><span class="list-icon">${icon(src.kind==='git'?'branch':'folder')}</span><div class="grow"><h3>${esc(src.name)}</h3><p class="mono">${esc(src.path)}</p></div><div class="tail">${pill(src.kind==='git'?'Git 仓库':'普通目录')}${ib('编辑来源 '+src.name,'edit-source:'+src.id,'edit')}</div></div>`).join('')}</div></section>`);}
function settingsPage(){const section=state.settings;const labels={providers:'模型服务',mcp:'MCP 连接',skills:'Skills',general:'通用'};let content='';if(section==='general')content=`<div class="settings-intro"><div><h2>本机与运行</h2><p>让任务在明确的边界内运行。</p></div></div><div class="list"><div class="list-row"><div class="grow"><h3>关闭窗口后继续运行</h3><p>应用留在后台；明确退出或系统休眠期间不执行定时任务。</p></div>${pill('开启','blue')}</div><div class="list-row"><div class="grow"><h3>错过的定时执行</h3><p>不自动补跑；同任务有未结束执行时跳过并记录。</p></div>${icon('clock')}</div><div class="list-row"><div class="grow"><h3>任务根目录</h3><p class="mono">~/.pidock/tasks</p></div>${pill('示例路径')}</div></div>`;else{const data=state[section],kind={providers:'Provider',mcp:'MCP',skills:'Skill'}[section];content=`<div class="settings-intro"><div><h2>${labels[section]}</h2><p>${{providers:'连接你选择的模型，让它用于每一次对话。',mcp:'管理工具连接，查看状态与调用来源。',skills:'把常用工作方式加入你的会话。'}[section]}</p></div>${btn('添加 '+kind,'add-config:'+section,'primary','plus')}</div><div class="list">${data.map(x=>`<div class="list-row"><span class="list-icon">${icon({providers:'cpu',mcp:'plug',skills:'book'}[section])}</span><div class="grow"><h3>${esc(x.name)}</h3><p>${esc(x.endpoint||x.path||x.transport+' · '+x.target)}</p>${section==='skills'?`<p>${esc(x.description)}</p>`:''}${section==='mcp'&&x.status==='error'?'<p style="color:#bd7868">连接失败：示例服务不可达。请检查配置后重试。</p>':''}</div><div class="tail">${section==='mcp'?pill({connected:'已连接',disconnected:'已停用',error:'连接失败'}[x.status],x.status==='connected'?'blue':x.status==='error'?'warn':''):''}<button class="toggle ${x.enabled?'on':''}" role="switch" aria-checked="${x.enabled}" aria-label="启停 ${esc(x.name)}" data-action="toggle-config:${section}:${x.id}"></button>${ib('编辑 '+x.name,`edit-config:${section}:${x.id}`,'more')}</div></div>`).join('')||'<div class="list-row muted">还没有配置，从右上角添加。</div>'}</div><div class="config-state">${section==='providers'?'认证在正式产品中由本机私有保存；原型不采集或保存真实密钥。':'配置变化在下一轮安全会话边界生效。此处仅模拟配置与状态。'}</div>`;}return page('设置','恰好够用的配置，专注于手头的事。','',`<div class="settings-layout"><nav class="settings-nav" aria-label="设置分类">${Object.entries(labels).map(([k,v])=>`<button class="${k===section?'active':''}" data-action="settings:${k}">${v}</button>`).join('')}</nav><div class="settings-content">${content}</div></div>`);}
const ruleText = s => `${s.rule==='daily'?'每天':s.rule==='weekly'?'每周一':s.rule==='once'?'一次性 · 11 月 3 日':'周一至周五'} ${s.time}`;
function schedulesPage(){return page('定时任务','把重复的事交给 Agent，每次结果都能继续聊。',btn('新建定时任务','new-schedule','primary','plus'),`<div class="schedule-grid"><div>${state.schedules.map(s=>{const t=state.tasks.find(t=>t.id===s.task);return `<article class="schedule-card"><div class="row between"><div class="row"><span class="list-icon">${icon('clock')}</span><div><h3>${esc(s.name)}</h3><span class="hint">${esc(state.projects.find(p=>p.id===t.project)?.name)} · ${esc(t.name)}</span></div></div><button class="toggle ${s.enabled?'on':''}" role="switch" aria-checked="${s.enabled}" aria-label="启停 ${esc(s.name)}" data-action="toggle-schedule:${s.id}" ${t.archived?'disabled':''}></button></div><p>${esc(s.prompt)}</p><div class="row wrap">${pill(ruleText(s))}${pill(s.timezone)}${pill(s.model)}</div><div class="schedule-footer">${btn('立即运行','run-schedule:'+s.id,'','play')}${btn('编辑','edit-schedule:'+s.id,'quiet')}<small>${s.enabled?'已启用':'已暂停'}</small></div></article>`;}).join('')||'<div class="preview">还没有定时任务，创建一个试试。</div>'}<div class="preview"><strong>运行规则</strong><br>应用运行时调度，关窗可继续后台运行。明确退出或休眠时不执行、不补跑。同任务已有执行或等待确认时，本次触发会跳过。<br>原型仅提供手动模拟，不注册真实调度。</div></div><section><div class="section-heading"><h2>最近执行</h2><span class="hint">每次独立会话</span></div>${state.runs.slice().reverse().map(r=>`<div class="run-item">${icon(r.status==='已完成'?'check':r.status==='已跳过'?'clock':'message')}<div class="grow"><div class="row between"><h3>${esc(r.title)}</h3>${pill(r.status,r.status==='已完成'?'blue':'')}</div><p>${esc(r.time)} · ${esc(r.reason)}</p>${r.session?`<button data-action="open-run:${r.id}">查看结果并继续聊 ${icon('chevron')}</button>`:''}</div></div>`).join('')}</section></div>`);}
function archivePage(){const tasks=state.tasks.filter(t=>t.archived);return page('已归档','保留已经结束的任务，需要时再继续。','',`<div class="list">${tasks.map(t=>`<div class="list-row"><span class="list-icon">${icon('archive')}</span><div class="grow"><h3>${esc(t.name)}</h3><p>${esc(state.projects.find(p=>p.id===t.project)?.name)} · ${t.sessions.length} 个会话 · 来源文件仍保留</p></div><div class="tail">${btn('查看','task:'+t.id,'quiet')}${btn('恢复','restore-archived-task:'+t.id)}${ib('清理任务 '+t.name,'cleanup:'+t.id,'trash')}</div></div>`).join('')||`<div class="empty-chat">${icon('archive')}<h2 style="margin-top:18px">这里还很清爽。</h2><p>归档后的任务会出现在这里，历史与目录都不会因归档而删除。</p></div>`}</div><div class="preview">会话归档在各任务的「全部会话」中查看。任务清理是独立操作，不会删除共享原文件。</div>`);}
function modal(title,body,footer='',wide=false){$('#modal-root').innerHTML=`<div class="modal-shade"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${esc(title)}</h2>${ib('关闭对话框','close','close')}</header><div class="modal-body">${body}</div><footer class="modal-footer">${btn('取消','close','quiet')}${footer}</footer></section></div>`;modal.previous=document.activeElement;requestAnimationFrame(()=>$('.modal input,.modal textarea,.modal select,.modal button')?.focus());}
function closeModal(){$('#modal-root').innerHTML='';modal.previous?.isConnected&&modal.previous.focus();}
function field(label,id,value='',type='text',hint=''){return `<label class="field"><span>${esc(label)}</span><input id="${id}" type="${type}" value="${esc(value)}" ${type==='password'?'autocomplete="off"':''}>${hint?`<small>${esc(hint)}</small>`:''}</label>`;}
function value(id){return $('#'+id)?.value.trim()||'';}
function saveDraft(){if($('#draft')&&currentSession())currentSession().draft=$('#draft').value;}
function taskDialog(scheduled=false){state.creationKey=crypto.randomUUID().slice(0,6);state.taskType=scheduled?'scheduled':'manual';const p=currentProject();modal('新建任务',`<p>为一个明确的目标准备目录，并开始对话。</p>${field('任务名称','task-name','') }<div class="choice-row"><button class="choice ${scheduled?'':'active'}" data-action="task-type:manual"><strong>普通任务</strong><small>手动开始，随时继续</small></button><button class="choice ${scheduled?'active':''}" data-action="task-type:scheduled"><strong>定时任务</strong><small>按计划创建独立会话</small></button></div><span class="hint">选择 ${esc(p.name)} 中的来源，可逐个指定方式</span>${p.sources.map((src,i)=>`<div class="source-choice"><label class="row"><input type="checkbox" name="task-source" value="${src.id}" ${i===0?'checked':''}><strong>${esc(src.name)}</strong>${pill(src.kind==='git'?'Git 仓库':'普通目录')}</label>${src.kind==='git'?`<div class="form-grid"><label class="field"><span>目录方式</span><select id="mode-${src.id}" data-preview-source>${options([['worktree','独立 worktree'],['existing','使用已有目录']],'worktree')}</select></label><label class="field"><span>基准分支</span><input id="base-${src.id}" value="origin/main" data-preview-source></label></div>`:`<div class="hint" style="margin-top:8px">使用原文件 · 与其他任务共享</div>`}<div class="mono hint">${esc(src.path)}</div></div>`).join('')}<div class="preview" id="task-preview"></div><label class="row hint" style="margin-top:14px"><input type="checkbox" id="simulate-failure">演示一次 worktree 部分准备失败</label>`,btn(scheduled?'下一步：执行规则':'创建任务','create-task','primary'),true);updatePreview();}
function updatePreview(){const box=$('#task-preview');if(!box)return;const name=value('task-name')||'new-task';const selected=[...document.querySelectorAll('input[name="task-source"]:checked')].map(x=>findSource(x.value));box.innerHTML=`<strong>创建前预览</strong><br>${selected.map(src=>{const wt=src.kind==='git'&&value('mode-'+src.id)==='worktree';return `${esc(src.name)} · ${wt?'独立副本':'共享原文件'}<br><span class="mono">${esc(wt?'~/.pidock/tasks/'+name+'-'+state.creationKey+'/'+src.name:src.path)}</span>${wt?'<br>从本次成功 fetch 后固定的提交创建 · '+esc(value('base-'+src.id)):''}`;}).join('<br>')||'请选择至少一个来源。'}<br>所有操作仅模拟，不读取或改动磁盘。`;}
function createTask(){const name=value('task-name');const chosen=[...document.querySelectorAll('input[name="task-source"]:checked')].map(x=>findSource(x.value));if(!name||!chosen.length){notify('请填写任务名称并选择至少一个来源');return;}const t={id:'task-'+crypto.randomUUID(),project:state.project,name,sources:chosen.map(src=>{const mode=src.kind==='git'?value('mode-'+src.id):'existing';return {...src,mode,branch:mode==='worktree'?'codex/'+name+'-'+state.creationKey:'当前分支',base:value('base-'+src.id),path:mode==='worktree'?'~/.pidock/tasks/'+name+'-'+state.creationKey+'/'+src.name:src.path};}),sessions:[session('新会话')],active:0,archived:false,scheduled:state.taskType==='scheduled',creationFailed:$('#simulate-failure').checked&&chosen.some(src=>src.kind==='git'&&value('mode-'+src.id)==='worktree')};state.tasks.push(t);state.task=t.id;state.inspector=!!t.creationFailed;state.view='task';closeModal();render();if(t.scheduled)scheduleDialog(null,t);else notify(t.creationFailed?'任务已保留，侧栏可查看失败与恢复入口':'已创建演示任务');}
function projectDialog(edit=false){const p=currentProject();modal(edit?'编辑项目':'新建项目',`${field('项目名称','project-name',edit?p.name:'')}${field('说明','project-description',edit?p.description:'')}<div class="preview">项目只负责组织可复用的来源和任务，不是额外的顶层工作空间。</div>`,btn('保存','save-project:'+String(edit),'primary'));}
function sourceDialog(id){const src=currentProject().sources.find(x=>x.id===id);modal(src?'编辑来源':'添加来源',`${field('显示名称','source-name',src?.name)}<label class="field"><span>来源类型</span><select id="source-kind">${options([['git','Git 仓库'],['directory','普通目录']],src?.kind||'git')}</select></label>${field('本机路径','source-path',src?.path||'~/Developer/','text','原型填写示例路径，不打开磁盘选择器。')}<div class="preview">已有任务继续沿用原绑定。改名不改变来源身份，移除引用不删除原文件。</div>`,`${src?btn('移除引用','remove-source:'+src.id,'danger'):''}${btn('保存','save-source:'+(src?.id||'new'),'primary')}`);}
function sessionsDialog(){const t=currentTask();modal('全部会话',`<input class="filter-input" id="session-search" aria-label="搜索会话" placeholder="搜索会话名称…"><div class="page-tabs"><button class="page-tab ${state.sessionFilter==='active'?'active':''}" data-action="session-filter:active">未归档</button><button class="page-tab ${state.sessionFilter==='archived'?'active':''}" data-action="session-filter:archived">已归档</button></div><div id="session-list">${sessionRows(t,'')}</div>`,btn('新建会话','new-session','primary','plus'));}
function sessionRows(t,q){return t.sessions.map((s,i)=>({s,i})).filter(({s})=>(state.sessionFilter==='archived')===s.archived&&s.name.toLowerCase().includes(q.toLowerCase())).map(({s,i})=>`<div class="modal-list-row"><span class="dot ${s.status==='running'?'blue':''}"></span><button class="grow" style="text-align:left" data-action="session:${i}">${esc(s.name)}<small>${s.messages.length} 条消息 · ${s.status==='running'?'执行中':'空闲'}</small></button>${btn('重命名','rename-session:'+i,'quiet')}${btn(s.archived?'恢复':'归档',`${s.archived?'unarchive':'archive'}-session:${i}`,'quiet')}${ib('删除会话 '+s.name,'delete-session:'+i,'trash')}</div>`).join('')||'<p class="hint">没有匹配的会话。</p>';}
function newSession(){saveDraft();const t=currentTask();if(t.archived){notify('请先恢复任务');return;}const created=session('新会话 '+(t.sessions.length+1));if(currentSession()){created.provider=currentSession().provider;created.model=currentSession().model;created.permission=currentSession().permission;}t.sessions.push(created);t.active=t.sessions.length-1;closeModal();render();$('#draft')?.focus();}
function sessionMenu(){const s=currentSession();if(!s){sessionsDialog();return;}const i=currentTask().active;modal('会话操作',`<p>${esc(s.name)} · 操作仅影响这个会话。</p><div class="row wrap">${btn('重命名','rename-session:'+i,'','edit')}${btn(s.archived?'恢复会话':'归档会话',`${s.archived?'unarchive':'archive'}-session:${i}`,'','archive')}${btn('删除会话','delete-session:'+i,'danger','trash')}</div><div class="preview">全新对话使用「新建会话」。删除会话不会删除任务、worktree 或用户原始文件。</div>`);}
function taskMenu(){const t=currentTask();modal('任务操作',`<p>${esc(t.name)}</p><div class="row wrap">${btn('重命名任务','rename-task','','edit')}${btn(t.archived?'恢复任务':'归档任务',t.archived?'restore-task':'archive-task','','archive')}${btn('查看目录','show-inspector','','folder')}</div><div class="preview">任务归档会停止在途执行并暂停定时规则。恢复后不会自动运行。</div>`,btn('演示准备失败','demo-preparation','quiet'));}
function stopSessions(t){for(const s of t.sessions){if(['running','approval'].includes(s.status)){s.status='stopped';s.messages.push({role:'agent',text:'本轮已停止。已完成的操作不会自动回滚；你可以继续发送新的请求。',time:time()});}}}
function archiveSession(index,archive=true){const t=currentTask(),s=t.sessions[index];if(!s)return;stopOne(s);s.archived=archive;closeModal();render();notify(archive?'会话已归档，历史和草稿保留':'会话已恢复，未自动执行');}
function stopOne(s){if(['running','approval'].includes(s.status)){s.status='stopped';s.messages.push({role:'agent',text:'执行已停止，保留已完成结果。',time:time()});}}
function confirmDelete(index){const t=currentTask(),s=t.sessions[index];modal('删除这个会话？',`<p>仅删除「${esc(s.name)}」的对话历史与草稿。任务、其他会话、工作副本与用户原始目录均保留。</p><div class="danger-note">${s.messages.length} 条消息及本会话草稿将从演示中移除。${['running','approval'].includes(s.status)?'先停止执行与回收所属资源，再移除记录。':''}<br>对应定时记录会保留「会话已删除」状态。</div>`,btn('删除会话','confirm-delete:'+index,'danger'));}
function permissions(){modal('会话权限',`<p>限定 Agent 在当前任务来源内的操作。本原型不执行真实操作。</p><div class="choice-row"><button class="choice ${currentSession().permission==='read'?'active':''}" data-action="set-permission:read"><strong>只读模式</strong><small>可读取与搜索，不修改文件或执行写命令</small></button><button class="choice ${currentSession().permission==='confirm'?'active':''}" data-action="set-permission:confirm"><strong>操作需确认</strong><small>对具体操作审阅，批准只作用于本次请求</small></button></div>`);}
function send(){saveDraft();const t=currentTask(),s=currentSession();if(!s||!s.draft.trim()||busy(t)||t.archived||s.archived||t.creationFailed)return;const provider=state.providers.find(p=>p.id===s.provider&&p.enabled);if(!provider||!provider.models.split(',').map(x=>x.trim()).includes(s.model)){notify('原 Provider 或模型不可用，请明确选择有效模型');return;}const text=s.draft.trim();s.messages.push({role:'user',text,time:time()});s.draft='';s.pendingSkill=s.skill?.name;s.skill=null;s.status='running';s.context=Math.min(78,s.context+3);closeModal();render();scrollChat();const id=s.id;setTimeout(()=>{if(s.id!==id||s.status!=='running')return;if(text.includes('失败')){s.status='failed';s.draft=text;s.messages.push({role:'agent',text:'演示连接失败：Provider 请求未获得响应。你的输入已放回草稿；没有自动重试或替换模型。',time:time()});}else if(s.permission==='confirm'&&(/测试|执行|修改|写入/.test(text))){s.status='approval';}else{s.status='idle';s.messages.push({role:'agent',text:s.permission==='read'?'已按只读模式完成示例分析。我会先阅读当前任务的来源、梳理结构并列出建议。本轮没有修改文件或执行写操作。':'我会先查看任务来源并梳理具体步骤，再与你确认需要执行的操作。这里展示模拟回复，用于评审对话、模型选择与会话切换。',time:time(),model:s.model,skill:s.pendingSkill});}if(currentSession()?.id===s.id){render();scrollChat();}},1800);}
function scrollChat(){requestAnimationFrame(()=>{const c=$('#conversation');if(c)c.scrollTop=c.scrollHeight;});}
function approval(){modal('审阅本次操作',`<p>目标：${esc(currentTask().name)} / ${esc(currentSession().name)}</p><div class="approval-command">npm test<br>cwd: ${esc(currentTask().sources[0]?.path)}</div><div class="preview">范围：仅当前任务来源；可能产生测试缓存。批准只适用于当前命令和目标。其他会话仍可编辑草稿，不能开始新执行。<br>这是演示请求，不运行真实命令。</div>`,`${btn('拒绝本次','reject','quiet')}${btn('批准一次','approve','primary')}`);}
function configDialog(kind,id){const item=state[kind].find(x=>x.id===id);const labels={providers:'Provider',mcp:'MCP 连接',skills:'Skill'};let fields=field('名称','config-name',item?.name);if(kind==='providers')fields+=`${field('服务地址','config-target',item?.endpoint||'https://api.example.com/v1')}${field('模型名称（英文逗号分隔）','config-models',item?.models||'') }<label class="field"><span>认证凭据</span><input disabled placeholder="API Key · 原型不接收真实凭据"><small>正式产品使用本机私有存储，支持替换或移除凭据。</small></label><div class="preview">正式产品在本机私有保存认证。原型不提供密钥输入，不验证连接；保存后模型将出现在演示会话选择器中。</div>`;if(kind==='mcp')fields+=`<label class="field"><span>传输方式</span><select id="config-transport">${options([['stdio','stdio · 本机命令'],['http','HTTP · 远程地址']],item?.transport||'stdio')}</select></label>${field('命令或服务地址','config-target',item?.target||'')}<div class="preview">连接、资源回收与工具调用仅为状态演示。添加连接不代表生产 Host 已加载。</div>`;if(kind==='skills')fields+=`${field('本地来源路径','config-target',item?.path||'~/.agents/skills/')}${field('说明','config-description',item?.description||'')}<div class="preview">来源会显示在配置和会话引用中。模拟加载后可在输入框使用 $ 选择。</div>`;modal((item?'编辑 ':'添加 ')+labels[kind],fields,`${kind==='mcp'&&item?btn('模拟连接失败','mcp-error:'+item.id,'quiet'):''}${item?btn('移除',`remove-config:${kind}:${item.id}`,'danger'):''}${btn('保存',`save-config:${kind}:${item?.id||'new'}`,'primary')}`);}
function saveConfig(kind,id){const name=value('config-name'),target=value('config-target');if(!name||!target){notify('请填写名称和来源地址');return;}const old=state[kind].find(x=>x.id===id);let x={id:old?.id||crypto.randomUUID(),name,enabled:old?.enabled??true};if(kind==='providers'){if(!value('config-models')){notify('请填写至少一个模型');return;}x={...x,endpoint:target,models:value('config-models')};}if(kind==='mcp')x={...x,transport:value('config-transport'),target,status:x.enabled?'connected':'disconnected'};if(kind==='skills')x={...x,path:target,description:value('config-description')};if(old)state[kind][state[kind].indexOf(old)]=x;else state[kind].push(x);closeModal();render();notify('演示配置已保存，下一轮对话使用新配置');}
function skillDialog(){const enabled=state.skills.filter(x=>x.enabled);modal('选择技能',`<p>技能保留本地来源，加入当前会话的下一条消息。</p>${enabled.map(s=>`<button class="list-row" data-action="use-skill:${s.id}"><span class="list-icon">${icon('book')}</span><span class="grow"><h3>$${esc(s.name)}</h3><p>${esc(s.path)}</p></span>${icon('chevron')}</button>`).join('')||'<div class="preview">没有已启用的技能，请在设置中添加。</div>'}`);}
function scheduleDialog(id,task){const s=state.schedules.find(x=>x.id===id),t=task||state.tasks.find(x=>x.id===s?.task)||currentTask();if(!t||t.archived){notify('请先选择或创建未归档任务');return;}modal(s?'编辑定时任务':'执行规则',`<p>每次触发在「${esc(t.name)}」的固定目录中创建独立会话。</p>${field('名称','schedule-name',s?.name||t.name)}<label class="field"><span>提示词</span><textarea id="schedule-prompt">${esc(s?.prompt||'检查最近一天的代码改动，整理风险与建议。')}</textarea></label><div class="form-grid"><label class="field"><span>周期</span><select id="schedule-rule">${options([['weekdays','周一至周五'],['daily','每天'],['weekly','每周一'],['once','一次性 · 2026-11-03']],s?.rule||'weekdays')}</select></label>${field('执行时间','schedule-time',s?.time||'09:15','time')}</div><div class="form-grid"><label class="field"><span>时区</span><select id="schedule-timezone">${options([['Asia/Shanghai','Asia/Shanghai'],['UTC','UTC']],s?.timezone||'Asia/Shanghai')}</select></label><label class="field"><span>会话权限</span><select id="schedule-permission">${options([['read','只读模式'],['confirm','操作需确认']],s?.permission||'read')}</select></label></div><label class="field"><span>Provider / 模型</span><select id="schedule-model">${modelOptions().map(m=>`<option value="${esc(m.provider+'|'+m.model)}" ${s&&m.provider===s.provider&&m.model===s.model?'selected':''}>${esc(m.name+' / '+m.model)}</option>`).join('')}</select></label><div class="preview">${s?'保存配置不会延长在途审批或重放旧执行。':'保存后默认暂停，由你手动启用。'}退出或休眠不执行、不补跑，同任务忙碌时跳过。这里不计算真实调度时间。</div>`,btn('保存执行规则',`save-schedule:${s?.id||'new'}:${t.id}`,'primary'),true);}
function saveSchedule(id,taskId){const name=value('schedule-name'),prompt=value('schedule-prompt'),clock=value('schedule-time'),selection=value('schedule-model');if(!name||!prompt||!clock||!selection){notify('请填写名称、提示词、时间和有效模型');return;}const old=state.schedules.find(s=>s.id===id),[provider,model]=selection.split('|');const s={id:old?.id||crypto.randomUUID(),task:taskId,name,prompt,rule:value('schedule-rule'),time:clock,timezone:value('schedule-timezone'),permission:value('schedule-permission'),provider,model,enabled:old?.enabled??false};if(old)state.schedules[state.schedules.indexOf(old)]=s;else state.schedules.push(s);state.tasks.find(t=>t.id===taskId).scheduled=true;go('schedules');notify('执行规则已保存'+(s.enabled?'':'，当前暂停'));}
function runSchedule(id){const rule=state.schedules.find(s=>s.id===id),t=state.tasks.find(t=>t.id===rule.task);const r={id:crypto.randomUUID(),task:t.id,title:rule.name,time:'今天 '+time(),session:null};if(t.creationFailed){r.status='失败';r.reason='任务目录准备未完成';state.runs.push(r);render();return;}if(t.archived){notify('请先恢复任务，不能绕过归档执行');return;}if(busy(t)){r.status='已跳过';r.reason='同任务有未结束执行（包括等待确认）';}else{const p=state.providers.find(p=>p.id===rule.provider&&p.enabled);if(!p||!p.models.split(',').map(m=>m.trim()).includes(rule.model)){r.status='失败';r.reason='所选 Provider 或模型已失效，没有自动替换';}else{const s=session('手动执行 · '+time());s.model=rule.model;s.provider=rule.provider;s.permission=rule.permission;s.messages=[{role:'user',text:rule.prompt,time:time()},{role:'agent',text:'本次定时任务已模拟完成。新建了独立会话，使用原任务目录，不继承其他执行的聊天上下文。你可以继续追问本次结果。',time:time(),model:s.model}];t.sessions.push(s);r.session=s.id;r.status='已完成';r.reason='独立会话 · 手动模拟';}}state.runs.push(r);render();notify(r.status==='已跳过'?r.reason:'已记录一次模拟执行');}
function searchDialog(){modal('搜索项目与任务',`<input class="filter-input" id="global-search" aria-label="搜索项目与任务" placeholder="输入项目或任务名称…"><div class="search-results" id="search-results">${searchResults('')}</div>`);}
function searchResults(q){const projects=state.projects.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())).map(p=>`<button class="list-row" data-action="project:${p.id}">${icon('folder')}<span class="grow"><h3>${esc(p.name)}</h3><p>项目 · ${esc(p.description)}</p></span>${icon('chevron')}</button>`).join('');return projects+state.tasks.filter(t=>t.name.toLowerCase().includes(q.toLowerCase())).map(t=>`<button class="list-row" data-action="task:${t.id}">${icon(t.scheduled?'clock':'message')}<span class="grow"><h3>${esc(t.name)}</h3><p>${esc(state.projects.find(p=>p.id===t.project)?.name)}${t.archived?' · 已归档':''}</p></span>${icon('chevron')}</button>`).join('')||'<p class="hint">没有找到任务。</p>';}
function notes(){modal('首版 UI · 设计说明',`<p>以 2026-11-02 最新 #135 为范围。本页是设计评审原型，刷新会重置全部数据。</p><div class="list"><div class="list-row"><div><h3>A · Apple 侧栏</h3><p>浅灰导航、单一白色画布；会话是视觉中心，任务信息按需打开。</p></div></div><div class="list-row"><div><h3>B · 扁平分栏</h3><p>全局图标栏与项目任务分栏；适合频繁切换任务，更偏桌面效率工具。</p></div></div></div><div class="preview"><strong>建议体验</strong><br>1. 新建任务：混选仓库与普通目录，比较已有目录 / worktree。<br>2. 切换会话：分别写草稿，归档、恢复或删除会话。<br>3. 设置：添加模型、MCP、Skills，再回到会话选择。<br>4. 定时任务：立即运行，打开独立会话并继续聊。<br>5. 对话发送「执行测试」演示审批；发送「失败」演示失败保留输入。<br>6. 任务操作 → 演示准备失败 → 侧栏恢复准备。</div><p style="margin-top:16px">所有模型回复、命令、Git、路径、配置与调度均为模拟。没有磁盘或网络操作；未连接生产 Host，也未开始正式产品实现。</p>`,btn('开始体验','close','primary'),true);}
function dispatch(action){saveDraft();const [type,...args]=action.split(':');const arg=args.join(':');switch(type){
case 'view':go(arg);break;
case 'variant':variant(arg);break;
case 'toggle-nav':state.nav=!state.nav;render();break;
case 'project':state.project=arg;go('projects');break;
case 'task':selectTask(arg);break;
case 'new-task':taskDialog();break;
case 'task-type':state.taskType=arg;document.querySelectorAll('.choice-row .choice').forEach(el=>el.classList.toggle('active',el.dataset.action==='task-type:'+arg));$('.modal-footer .primary').textContent=arg==='scheduled'?'下一步：执行规则':'创建任务';break;
case 'create-task':createTask();break;
case 'new-project':projectDialog();break;
case 'edit-project':projectDialog(true);break;
case 'save-project':{const name=value('project-name');if(!name){notify('请填写项目名称');break;}if(arg==='true'){Object.assign(currentProject(),{name,description:value('project-description')});}else{const p={id:crypto.randomUUID(),name,description:value('project-description'),sources:[]};state.projects.push(p);state.project=p.id;}go('projects');break;}
case 'add-source':sourceDialog();break;
case 'edit-source':sourceDialog(arg);break;
case 'save-source':{const name=value('source-name'),path=value('source-path');if(!name||!path){notify('请填写名称和路径');break;}const p=currentProject(),old=p.sources.find(x=>x.id===arg),x={id:old?.id||crypto.randomUUID(),name,path,kind:value('source-kind')};if(old)p.sources[p.sources.indexOf(old)]=x;else p.sources.push(x);go('projects');break;}
case 'remove-source':currentProject().sources=currentProject().sources.filter(x=>x.id!==arg);go('projects');notify('已移除项目引用，任务绑定与原始文件保留');break;
case 'filter':state.taskFilter=arg;render();break;
case 'toggle-inspector':state.inspector=!state.inspector;render();break;
case 'show-inspector':state.inspector=true;closeModal();render();break;
case 'new-session':newSession();break;
case 'session':currentTask().active=Number(arg);closeModal();render();break;
case 'sessions':sessionsDialog();break;
case 'session-filter':state.sessionFilter=arg;sessionsDialog();break;
case 'session-menu':sessionMenu();break;
case 'rename-session':{const s=currentTask().sessions[Number(arg)];modal('重命名会话',field('会话名称','rename-value',s.name),btn('保存','save-session-name:'+arg,'primary'));break;}
case 'save-session-name':if(value('rename-value')){currentTask().sessions[Number(arg)].name=value('rename-value');closeModal();render();}break;
case 'archive-session':archiveSession(Number(arg));break;
case 'unarchive-session':archiveSession(Number(arg),false);break;
case 'restore-session':archiveSession(currentTask().active,false);break;
case 'delete-session':confirmDelete(Number(arg));break;
case 'confirm-delete':{const t=currentTask(),s=t.sessions[Number(arg)];stopOne(s);state.runs.filter(r=>r.session===s.id).forEach(r=>{r.session=null;r.reason='会话已删除 · 执行记录保留';});t.sessions.splice(Number(arg),1);t.active=Math.max(0,Math.min(t.active,t.sessions.length-1));closeModal();render();notify('已删除指定会话，任务与来源文件保留');break;}
case 'task-menu':taskMenu();break;
case 'rename-task':modal('重命名任务',field('任务名称','rename-value',currentTask().name),btn('保存','save-task-name','primary'));break;
case 'save-task-name':if(value('rename-value')){currentTask().name=value('rename-value');closeModal();render();}break;
case 'archive-task':modal('归档任务？',`<p>停止「${esc(currentTask().name)}」的在途执行，暂停所属定时规则，保留历史与全部来源文件。</p>`,btn('归档任务','confirm-archive-task','primary'));break;
case 'confirm-archive-task':{const t=currentTask();stopSessions(t);t.archived=true;state.schedules.filter(s=>s.task===t.id).forEach(s=>s.enabled=false);go('archive');break;}
case 'restore-task':currentTask().archived=false;closeModal();render();notify('任务已恢复，未自动执行或启用定时规则');break;
case 'restore-archived-task':{const t=state.tasks.find(t=>t.id===arg);t.archived=false;render();notify('已恢复任务，定时规则保持暂停');break;}
case 'cleanup':{const t=state.tasks.find(t=>t.id===arg);modal('清理任务前确认',`<p>清理「${esc(t.name)}」的任务记录与受管资源。此演示不删除磁盘文件。</p><div class="preview">${t.sources.map(src=>`${esc(src.name)} · ${src.mode==='worktree'?'独立 worktree：检查未交付改动后保留副本，再清理受管目录':'共享原文件：始终保留'}`).join('<br>')}<br>会话与草稿：随任务移除；定时执行记录保留任务已清理状态。</div><label class="row hint" style="margin-top:14px"><input type="checkbox" id="cleanup-confirm">我已审阅以上范围，确认移除演示记录</label>`,btn('确认清理','confirm-cleanup:'+arg,'danger'));break;}
case 'confirm-cleanup':if($('#cleanup-confirm').checked){state.tasks=state.tasks.filter(t=>t.id!==arg);state.schedules=state.schedules.filter(s=>s.task!==arg);state.runs.filter(r=>r.task===arg).forEach(r=>{r.session=null;r.reason='任务已清理 · 记录保留';});go('archive');notify('演示记录已清理，共享原文件始终保留');}else notify('请先审阅并勾选清理范围');break;
case 'permission':permissions();break;
case 'set-permission':if(busy(currentTask())){notify('请先结束当前执行，权限在安全边界调整');break;}currentSession().permission=arg;closeModal();render();break;
case 'suggest':currentSession().draft=arg;render();$('#draft').focus();break;
case 'reference':modal('引用任务来源',`<p>将任务中已选来源的路径加入草稿，不打开独立文件管理器。</p>${currentTask().sources.map(s=>`<button class="list-row" data-action="reference-source:${s.id}">${icon('folder')}<div class="grow"><h3>${esc(s.name)}</h3><p>${esc(s.path)}</p></div>${icon('plus')}</button>`).join('')}`,btn('选择 Skill','skills','quiet','book'));break;
case 'reference-source':{const src=currentTask().sources.find(s=>s.id===arg);currentSession().draft+='\n@'+src.name+' ('+src.path+')';closeModal();render();break;}
case 'skills':skillDialog();break;
case 'use-skill':currentSession().skill=state.skills.find(s=>s.id===arg);currentSession().draft=currentSession().draft.replace(/\$$/,'');closeModal();render();$('#draft').focus();break;
case 'remove-skill':currentSession().skill=null;render();break;
case 'send':send();break;
case 'stop':stopOne(currentSession());render();notify('已停止本轮演示，保留完成结果');break;
case 'approval':approval();break;
case 'reject':currentSession().status='idle';currentSession().messages.push({role:'agent',text:'你拒绝了本次命令。没有执行操作，可以修改请求后继续。',time:time()});closeModal();render();scrollChat();break;
case 'approve':currentSession().status='idle';currentSession().messages.push({role:'agent',text:'已模拟执行本次获准的 npm test，示例退出码为 0。批准仅作用于这一条命令；没有运行真实测试。',time:time()});closeModal();render();scrollChat();break;
case 'settings':state.settings=arg;go('settings');break;
case 'mcp-error':{const x=state.mcp.find(x=>x.id===arg);x.status='error';closeModal();render();break;}
case 'add-config':configDialog(arg);break;
case 'edit-config':configDialog(args[0],args[1]);break;
case 'save-config':saveConfig(args[0],args[1]);break;
case 'remove-config':{const[k,id]=args;state[k]=state[k].filter(x=>x.id!==id);closeModal();render();notify('已移除演示配置；原会话保留原模型身份，不自动替换');break;}
case 'toggle-config':{const[k,id]=args,x=state[k].find(v=>v.id===id);x.enabled=!x.enabled;if(k==='mcp')x.status=x.enabled?'connected':'disconnected';render();break;}
case 'new-schedule':taskDialog(true);break;
case 'edit-schedule':scheduleDialog(arg);break;
case 'task-rule':scheduleDialog(state.schedules.find(rule=>rule.task===currentTask().id)?.id,currentTask());break;
case 'save-schedule':saveSchedule(args[0],args[1]);break;
case 'toggle-schedule':{const s=state.schedules.find(s=>s.id===arg);s.enabled=!s.enabled;render();break;}
case 'run-schedule':runSchedule(arg);break;
case 'open-run':{const r=state.runs.find(r=>r.id===arg),t=state.tasks.find(t=>t.id===r.task);if(!t||!r.session){notify('原会话已删除或任务已清理');break;}t.active=t.sessions.findIndex(s=>s.id===r.session);selectTask(t.id);break;}
case 'search':searchDialog();break;
case 'design-notes':notes();break;
case 'usage':modal('会话上下文',`<p>当前会话上下文占用：${currentSession().context}%（示例估计）。</p><div class="preview">上下文占用与累计 Token 消耗分开记录。首版只保留会话必需状态，不提供复杂跨项目用量报表。</div>`);break;
case 'demo-preparation':if(!currentTask().sources.some(src=>src.mode==='worktree')){notify('该任务使用已有目录，没有 worktree 准备步骤');break;}currentTask().creationFailed=true;state.inspector=true;closeModal();render();break;
case 'recover-worktree':currentTask().creationFailed=false;render();notify('已模拟重新获取远程基线并恢复准备，原目录未覆盖');break;
case 'close':closeModal();break;
}}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){dispatch(action.dataset.action);return;}if(e.target.classList.contains('modal-shade'))closeModal();});
document.addEventListener('input',e=>{if(e.target.id==='draft'){currentSession().draft=e.target.value;if(e.target.value.endsWith('$'))skillDialog();}if(e.target.id==='task-name')updatePreview();if(e.target.id==='session-search')$('#session-list').innerHTML=sessionRows(currentTask(),e.target.value);if(e.target.id==='global-search')$('#search-results').innerHTML=searchResults(e.target.value);if(e.target.matches('[data-preview-source]'))updatePreview();});
document.addEventListener('change',e=>{if(e.target.name==='task-source'||e.target.matches('[data-preview-source]')){const src=e.target.closest('.source-choice');if(src){const mode=src.querySelector('[id^="mode-"]'),base=src.querySelector('[id^="base-"]');if(mode&&base)base.disabled=mode.value==='existing';}updatePreview();}if(e.target.id==='model-select'){const s=currentSession();if(busy(currentTask())){notify('请先结束当前执行，模型在安全边界切换');render();return;}[s.provider,s.model]=e.target.value.split('|');render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('.modal'))closeModal();else if(state.inspector){state.inspector=false;render();}else if(state.nav){state.nav=false;render();}return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog();return;}if(e.target.id==='draft'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send();return;}if($('.modal')){if(e.key==='Tab'){const nodes=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal select:not(:disabled),.modal textarea:not(:disabled)')].filter(x=>x.getClientRects().length);if(nodes.length&&e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus();}else if(nodes.length&&!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus();}}return;}if(e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.target.closest('[role="tablist"]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('.session-tab')],i=tabs.indexOf(e.target);tabs[(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length]?.click();return;}if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();variant(state.variant==='A'?'B':'A');}});
const route=new URLSearchParams(location.search).get('page');if(['projects','settings','schedules','archive'].includes(route))state.view=route;
render();
